WITH latest AS (
  SELECT player_api_id, attacking_work_rate, date,
         ROW_NUMBER() OVER (PARTITION BY player_api_id ORDER BY date::timestamp DESC, id DESC) rn
  FROM player_attributes
), cur AS (
  SELECT * FROM latest WHERE rn = 1 AND attacking_work_rate IN ('low','medium','high')
)
SELECT ROUND(100.0 * AVG(CASE WHEN attacking_work_rate='low' THEN 1.0 ELSE 0 END), 1) AS pct_low,
       COUNT(*) AS n
FROM cur;

